def test_net_route_orphaned_packet_discard():
    """Test _route_orphaned_packet discards when undeclared_output_behavior is discard."""
    graph_config = GraphConfig(
        nodes=[
            NodeConfig(name="Unknown", out_ports={"out": PortConfig()}),
        ],
        edges=[],
    )

    config = NetConfig(
        pools={"main": PoolConfig(id="main", spec=MainPoolConfig())},
        graph=graph_config,
        output_queues={},  # No specific queues
        catch_all_output_queue=None,  # No catch-all
        undeclared_output_behavior="discard",  # Discard undeclared
    )

    net = Net(config)

    # Register a packet value
    net._packet_store.register("pkt_789", "discard_value")

    # Route the packet (should be discarded)
    net._route_orphaned_packet(
        packet_id="pkt_789",
        from_node="Unknown",
        from_port="out",
        epoch_id="epoch_3",
    )

    # No queues should have packets
    assert len(net.list_output_queues()) == 0

    # Packet value should be consumed (discarded)
    with pytest.raises(KeyError):
        net._packet_store._get("pkt_789")


